   157→// addedRPCHandlerByTopic returns the RPC handlers that are added in the new map that are not present in the old map.
   158→func addedRPCHandlerByTopic(previous, next map[string]rpcHandler) map[string]rpcHandler {
   159→	added := make(map[string]rpcHandler)
   160→
   161→	for topic, handler := range next {
   162→		if _, ok := previous[topic]; !ok {
   163→			added[topic] = handler
   164→		}
   165→	}
   166→
   167→	return added
   168→}
