   183→// registerRPCHandlers for p2p RPC.
   184→func (s *Service) registerRPCHandlers() error {
   185→	// Get the current epoch.
   186→	currentSlot := s.cfg.clock.CurrentSlot()
   187→	currentEpoch := slots.ToEpoch(currentSlot)
   188→
   189→	// Get the RPC handlers for the current epoch.
   190→	handlerByTopic, err := s.rpcHandlerByTopicFromEpoch(currentEpoch)
   191→	if err != nil {
   192→		return errors.Wrap(err, "rpc handler by topic from epoch")
   193→	}
   194→
   195→	// Register the RPC handlers for the current epoch.
   196→	for topic, handler := range handlerByTopic {
   197→		s.registerRPC(topic, handler)
   198→	}
   199→
   200→	return nil
   201→}
